public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    Set<Integer> visitedNodeIds = new HashSet<>();

    Stack<Integer> stack = new Stack<>();
    stack.push(start[0] * n + start[1]);
    visited[0][0] = true;
    visitedNodeIds.add((start[0] * n) + start[1]);

    while (!stack.isEmpty()) {
        int current = stack.pop();
        int x = current / n;
        int y = current % n;

        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        int[] directions = {Up, Down, Left, Right}; // Simulated directions for demonstration
        for (int i = 0; i < directions.length; i++) {
            int nx = x + directions[i][0];
            int ny = y + directions[i][1];

            if (isValid(nx, ny, n) && !visited[nx][ny] && !visitedNodeIds.contains(nx * n + ny)) {
                stack.push(nx * n + ny);
                visited[nx][ny] = true;
                visitedNodeIds.add(nx * n + ny);
            }
        }
    }

    return "cannot be travelled";
}

