            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int n = arr.length;
    Arrays.sort(arr);

    int removeCount = (int) Math.ceil(n / 10.0);
    int actualRemoveCount = Math.min(removeCount, n - removeCount - 1) / 2;

    int start = removeCount;
    int end = n - removeCount - 1;

    double sum = 0;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }

    return sum / actualRemoveCount;
}

public double trimMean(int[] arr) {
    int size = arr.length, trimmedSize = (int) (size * 0.15);
    Arrays.sort(arr);
    return Arrays.stream(arr).skip(trimmedSize).limit(size - trimmedSize).average().getAsDouble();
}

public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int numElements = arr.length;
    int removeNum = (int) (numElements * 0.1);
    int remainingNum = numElements - removeNum * 2;

    double trimmedSum = 0;
    for (int i = removeNum; i < remainingNum + removeNum; i++) {
        trimmedSum += arr[i];
    }

    return trimmedSum / remainingNum;
}

public static double trimMean(int[] arr) {
    long sum = 0;
    int len = arr.length;
    Integer[] sorted = Arrays.stream(arr).boxed().sorted().toArray(Integer[]::new);

    double lowerLimit = sorted[(len * 5) / 100];
    double upperLimit = sorted[(len * 95) / 100];

    int left = 0, right = len - 1;
    while (left < right) {
        if (sorted[left] >= lowerLimit) {
            left++;
        }
        if (sorted[right] <= upperLimit) {
            right--;
        }
        sum += sorted[++left] + sorted[--right];
    }

    double trimmedSum = sum - (lowerLimit + upperLimit);
    double mean = trimmedSum / ((len * 2) - 100);
    return Math.round(mean * 100000) / 100000.0;
}

public double trimMean(int[] arr) {
    int halfIndex = (int) (arr.length * 0.25);
    Arrays.sort(arr);

    double sum = 0;
    for (int i = halfIndex; i < arr.length - halfIndex; i++) {
        sum += arr[i];
    }

    return sum / (arr.length - 2 * halfIndex);
}

public boolean canArrange(int[] arr, int k) {
        int[] freq = new int[k];

        for (int num : arr) {
            freq[(num % k) % k]++;
        }

        // Check if the pairs can be formed
        if ((num % 2 != 0 && k % 2 != 0) || freq[k / 2] % 2 == 1) {
            return false;
        }

        // Ensure that the frequency of each remainder class is even
        for (int i = 1; i < k; i++) {
            if (freq[i] % 2 != 0) {
                return false;
            }
        }

        return true;
    }

public boolean canArrange(int[] arr, int k) {
    // Initialize a counter for each possible remainder when divided by k
    int[] remainders = new int[k];
    for (int num : arr) {
        int remainder = num % k;
        remainders[remainder]++;
    }

    // Check if it's possible to pair numbers such that the sum of each pair is divisible by k
    for (int remainder = 0; remainder < k; remainder++) {
        // For remainder 0, count must be even
        if (remainder == 0 && remainder % 2 != 0) {
            return false;
        }
        // For other remainders, pairs must be formed
        if (remainders[remainder] != remainders[k - remainder]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    Map<Integer, Integer> counts = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        counts.put(remainder, counts.getOrDefault(remainder, 0) + 1);
    }
    int uniqueRemainders = counts.size();
    return uniqueRemainders % 2 == 0 || (uniqueRemainders == 1 && counts.get(0) % 2 == 0);
}

public boolean canArrange(int[] arr, int k) {
    int modFrequency = Arrays.stream(arr).boxed().collect(Collectors.groupingBy(Integer::mod).size());

    for (int i = 1; i <= k / 2; i++) {
        if (modFrequency[i] > modFrequency[k - i]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    Set<Integer> remainders = new HashSet<>();
    for (int num : arr) {
        int remainder = num % k;
        if (remainder == 0 || remainders.contains(k - remainder)) {
            remainders.add(remainder);
        } else {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] e : edges) {
        graph.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
        graph.computeIfAbsent(e[1], k -> new ArrayList<>()).add(e[0]);
    }

    boolean[] visited = new boolean[n];
    visited[0] = true;
    int result = 0;

    // Helper function to perform DFS and calculate time
    int dfs(int node) {
        int timeAdded = 1; // Time to collect an apple
        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor]) {
               visited[neighbor] = true;
                timeAdded += dfs(neighbor);

                // Collect an apple, time expected for the tree, multiplying by 2 to account for round trip
                if (hasApple[neighbor] || timeAdded > 1) {
                    result += timeAdded;
                }
            }
        }
        return timeAdded;
    }

    // Start DFS from node 0
    dfs(0);
    return result - 1; // Subtract 1 to exclude the time already taken to go back to node 0
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int total = 0;

    if (!hasApple[0]) {
        return total;
    }

    for (int[] edge : edges) {
        int a = edge[0];
        int b = edge[1];

        if (!hasApple[a]) {
            continue;
        }

        total += isProcessed[a];
        hasApple[a] = false;
        hasApple[b] = true;
        total += isProcessed[b];
        hasApple[b] = false;

        isProcessed[a] = isProcessed[b] = true;
    }

    return total;
}

