public String sortString(String s) {
        int len = s.length();
        StringBuilder result = new StringBuilder();

        if (s.isEmpty() || len == 1) {
            return s;
        }

        Set<Character> 
            chars = s.chars().mapToObj(c -> (char) c)
                           .collect(Collectors.toCollection(LinkedHashSet::new));
        int smallestIdx = 0;
        int largestIdx = len - 1;

        outer: 
        while (chars.size() > 0) {
            while (chars.contains(s.charAt(smallestIdx)) && 
                   chars.size() > 1) 
                smallestIdx++;

            while (chars.contains(s.charAt(largestIdx)) && 
                   chars.size() > 1) 
                largestIdx--;

            result.append(s.charAt(smallestIdx));
            result.append(s.charAt(largestIdx));

            chars.remove(s.charAt(smallestIdx));
            chars.remove(s.charAt(largestIdx));

            chars = chars.stream()
                           .filter(c -> c != s.charAt(smallestIdx) &&
                                          c != s.charAt(largestIdx))
                           .collect(Collectors.toCollection(LinkedHashSet::new));
        }

        return result.toString();
    }

public String sortString(String s) {
    StringBuilder sorted = new StringBuilder();
    int[] charCount = new int[128]; // ASCII character count array
    boolean[] pickedChar = new boolean[128]; // Array to track picked characters

    // Count occurrences of each character
    for (char c : s.toCharArray()) {
        charCount[c]++;
    }

    // Append characters to sorted in ascending order
    int i = 0;
    while (i < s.length()) {
        for (int c = 0; i < s.length() && charCount[c] > 0; c++) {
            if (!pickedChar[c]) {
                selectedChar(c, sorted, pickedChar);
                charCount[c]--;
                i++;
            }
        }
    }

    // Append characters to sorted in descending order
    for (int i = s.length() - 1; i >= 0 && charCount[i] > 0; i--) {
        for (int c = 127; i >= 0 && charCount[c] > 0; c--) {
            if (!pickedChar[c]) {
                selectedChar(c, sorted, pickedChar);
                charCount[c]--;
                i--;
            }
        }
    }

    return sorted.toString();
}

public String sortString(String s) {
    int[] charCount = new int[26];
    for (char ch : s.toCharArray()) {
        charCount[ch - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    boolean finished = false;

    while (!finished) {
        finished = true;

        // Append smallest character
        for (int i = 0; i < 26; i++) {
            if (charCount[i] > 0) {
                result.append((char) ('a' + i));
                charCount[i]--;
                finished = false;
                break;
            }
        }

        // Append largest character
        for (int i = 25; i >= 0; i--) {
            if (charCount[i] > 0) {
                result.append((char) ('a' + i));
                charCount[i]--;
                finished = false;
                break;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder sorted = new StringBuilder();
    int[] charCounts = new int[128];

    // Count the occurrences of each character in the input string
    for (char c : s.toCharArray()) {
        charCounts[c]++;
    }

    // Steps 1-6
    while (sorted.length() < s.length()) {
        // Find the smallest smallest character
        char smallest = 'z';
        for (int i = 'a'; i <= 'z'; i++) {
            if (charCounts[i] > 0 && i < smallest) {
                smallest = i;
            }
        }
        sorted.append(smallest);
        charCounts[smallest]--;

        // Find the largest smallest character
        char largest = 'a';
        for (int i = 'z'; i >= 'a'; i--) {
            if (charCounts[i] > 0 && i > largest) {
                largest = i;
            }
        }
        sorted.append(largest);
        charCounts[largest]--;
    }

    return sorted.toString();
}

public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    int i = 0, j = 25;
    StringBuilder res = new StringBuilder();
    while (i <= j) {
        if (count[i] > 0) {
            res.append((char) ('a' + i));
            count[i]--;
        }
        if (count[j] > 0) {
            res.append((char) ('a' + j));
            count[j]--;
        }
    }

    return res.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    if (sum % 2 != 0) {
        return false;
    }
    int target = sum / 2;
    int[] first = new int[nums.length / 2];
    int[] second = new int[nums.length - first.length];
    int i = 0, j = 0;
    for (int num : nums) {
        if (i < first.length) {
            first[i++] = num;
        } else {
            second[j++] = num;
        }
    }
    int leftSum = 0, rightSum = 0;
    for (int num : first) {
        leftSum += num;
    }
    for (int num : second) {
        rightSum += num;
    }
    for (int i = 0; i < first.length; i++) {
        if (leftSum == target && rightSum == target) {
            return true;
        }
        leftSum -= first[i];
        rightSum += first[i];
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    double totalSum = Arrays.stream(nums).mapToDouble(d -> d).sum();
    double[] subSum = new double[nums.length + 1];

    for (int i = 0; i < nums.length; i++) {
        subSum[i + 1] = subSum[i] + nums[i];

        // Check if any subarray has an average equal to total sum divided by subarray size
        if ((subSum[i + 1] * 2) == totalSum && i > 0) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    if (sum % 2 != 0) {
        return false;
    }
    int targetSum = sum / 2;
    int i = 0, j = nums.length - 1;
    while (i < j) {
        int currentSum = nums[i] + nums[j];
        if (currentSum == targetSum) {
            return true;
        } else if (currentSum < targetSum) {
            i++;
        } else {
            j--;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = Arrays.stream(nums).sum();
    int minTarget = sum / 2;
    if (minTarget == 0) return false;

    double target = (double) sum / 2;

    public boolean helper(int[] nums, int start, int sum, double target) {
        if (start == nums.length) return false;

        if (sum >= target && sum <= target * 2 - 1) {
            if (sum == target) return true;
            return helper(nums, start + 1, sum - nums[start], target) || helper(nums, start + 1, sum, target);
        }

        return helper(nums, start + 1, sum, target);
    }

    return helper(nums, 0, 0, target);
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = Arrays.stream(nums).sum();

    // If the total sum cannot be evenly divided into two parts, return false
    if (total % 2 != 0) {
        return false;
    }

    int target = total / 2;

    // Try all possible divisions for the first half of the array
    for (int i = 1; i <= n / 2; i++) {
        int sumFirstHalf = Arrays.stream(nums).limit(i).sum();
        int sumSecondHalf = total - sumFirstHalf;
        // Check if the second half can also be divided into two equal parts
        if (sumSecondHalf % 2 == 0 && sumSecondHalf / 2 == sumFirstHalf) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i-1], dp[i-2]);
    }

    return Math.min(dp[n-1], dp[n-2]);
}

public int minCostClimbingStairs(int[] cost) {
        if (cost == null || cost.length < 2) {
            return cost.length != 0 ? cost[0] : 0;
        }

        int[] dp = new int[cost.length + 1];
        dp[0] = 0;
        dp[1] = 0;

        for (int i = 2; i <= cost.length; i++) {
            dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
        }

        return dp[cost.length];
    }

public int minCostClimbingStairs(int[] cost) {   
    if (cost.length <= 1) {
        return cost[0]; // Base case: only one step
    }

    int[] dp = new int[cost.length]; // Dynamic programming array
    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]); // Base case: only two steps

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i]; // Update minimum cost
    }

    return dp[cost.length-1]; // Return the minimum cost to reach the top
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n >= 2) cost[1] += cost[0];
    for (int i = 2; i < n; i++) {
        cost[i] += Math.min(cost[i - 1], cost[i - 2]);
    }
    return Math.min(cost[n - 1], cost[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 1) {
        return 0;
    }

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return dp[n - 1];
}

