public boolean hasAllCodes(String s, int k) {
    String newSet = new String.substring(s, 0, s.length() - k + 1);
    for (int i = 1; i < k; i++) {
        newSet += newSet.charAt(newSet.length() - k + 1 + i);
    }
    HashSet<String> seen = new HashSet<>();
    for (int i = 0; i < s.length(); i++) {
        if (newSet.substring(i, i + k).equals(newSet.substring(i + 1, i + k + 1))){
            seen.add(newSet.substring(i, i + k));
        }
        if (seen.size() == newSet.length() / k) {
            return true;
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    int chars = 1 << k; 
    char[] set = new char[chars]; 
    byte value = 0;
    for (byte i = 0;  i < s.length(); i++) {
        value = (byte) ((value << 1) | (s.charAt(i) - '0'));
        if (i >= k - 1 && set[value] != 1) {
            set[value] = 1; 
        }
    }
    return Arrays.stream(set).allMatch(value -> value == 1);
}

public boolean hasAllCodes(String s, int k) {
    // Early return if the length of s is less than k * 2
    if (s.length() < k * 2) {
        return false;
    }

    // Use a set to store all unique window of length k within s
    Set<String> windowSet = new HashSet<>();
    // Iterate over the string to generate all possible windows of length k
    for (int i = 0; i <= s.length() - k; i++) {
        String window = s.substring(i, i + k);
        windowSet.add(window);
    }

    // Check if the set of all windows contains all values from 0 to k - 1
    for (int i = 0; i < k; i++) {
        if (!windowSet.contains(String.valueOf(i))) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    HashSet<String> seen = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        String subStr = s.substring(i, i + k);
        if (!seen.contains(subStr)) {
            seen.add(subStr);
            if (seen.size() == (1 << k)) {
                return true;
            }
        }
    }
    return seen.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    // Check if the string has at least k characters
    if (s.length() < k) {
        return false;
    }

    // Create a set to keep track of all possible binary strings of length k
    Set<String> binaryStrings = new HashSet<>();

    // Generate all possible binary strings of length k
    for (int i = 0; i < k; i++) {
        binaryStrings.add("0".repeat(i) + "1".repeat(k - i));
    }

    // Check if all possible binary strings of length k are present in the string
    return binaryStrings.containsAll(binaryStrings);
}

