public int findMinFibonacciNumbers(int k) {
    List<Integer> fib = new ArrayList<>();
    int a = 1, b = 1;
    while (b <= k) {
        fib.add(b);
        int next = a + b;
        a = b;
        b = next;
    }

    int res = 0;
    while (k > 0 && !fib.isEmpty()) {
        int f = fib.get(fib.size() - 1);
        if (f == k) {
            res++;
            fib.remove(fib.size() - 1);
        } else if (f < k) {
            k -= f;
            res++;
        } else {
            fib.remove(fib.size() - 1);
        }
    }

    return res;
}

public int findMinFibonacciNumbers(int k) {
    if (k == 0) {
        return 0;
    }

    BigInteger prev = BigInteger.ONE;
    BigInteger cur = BigInteger.ONE;
    List<BigInteger> fibonacciNumbers = new ArrayList<>();
    fibonacciNumbers.add(prev);
    fibonacciNumbers.add(cur);

    while (cur.compareTo(BigInteger.valueOf(k)) <= 0) {
        fibonacciNumbers.add(cur);
        BigInteger next = prev.add(cur);
        prev = cur;
        cur = next;
    }

    int count = 0;
    for (int i = fibonacciNumbers.size() - 1; i >= 0; i--) {
        while (k >= fibonacciNumbers.get(i)) {
            k -= fibonacciNumbers.get(i);
            count++;
        }
    }

    return count;
}

