public String makeGood(String s) {
    boolean removing = true;
    StringBuffer sb = new StringBuffer();
    char prev = '#';
    while (removing) {
        removing = false;
        for (int i = 0; i < s.length() - 1; i++) {
            if (s.charAt(i) == prev) {
                prev = '#';
                i++;
            } else if ((s.charAt(i) - prev) * (prev - 'a') == 32) {
                sb.append(prev);
                prev = '#';
                removing = true;
                break;
            } else {
                sb.append(s.charAt(i));
            }
        }
        if (removing) {
            s = sb.toString();
            sb.delete(0, sb.length());
        }
    }
    return s;
}

