public int minOperations(String[] logs) {
    // Stack to simulate directory navigation
    Stack<String> stack = new Stack<>();

    // Iterate through each log
    for (String log : logs) {
        // If the log is a "../", pop from the stack
        if (log.equals("../")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else if (!log.equals(".")) {
            // Otherwise, push the log onto the stack
            stack.push(log);
        }
    }

    // Return the number of steps required (path from root to main)
    return stack.size();
}

