public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    int maxChar = 'a' + n - 1;

    for (int i = 0; i < n; i++) {
        while (k >= maxChar - 'a' + 1) {
            sb.append((char) maxChar);
            k -= maxChar - 'a' + 1;
        }
        sb.append(maxChar);
        k--;
        maxChar--;
    }

    return sb.toString();
}

public String getSmallestString(int n, int k) {
    char[] smallestString = new char[n];
    for (int i = n - 1; i >= 0; i--) {
        if (k >= 26) {
            smallestString[i] = 'a' + (k - 26);
            k = 0;
        } else {
            smallestString[i] = 'a' + k;
            k = 0;
        }
    }
    return new String(smallestString);
}

String getSmallestString(int n, int k) {
    // Initialize a StringBuilder with n 'a's
    StringBuilder sb = new StringBuilder();
    sb.append("a".repeat(n));

    // Calculate the number of 'a's required to reach the desired value k
    int countA = n - k;

    // Reverse the string to place 'a's at the beginning
    sb.reverse();

    // Remove 'a's until we reach the desired value k
    for (int i = 0; i < countA; i++) {
        int pos = sb.indexOf("aa");
        if (pos == 0) {
            sb.setCharAt(0, 'z');
        } else {
            sb.deleteCharAt(pos - 1);
        }
    }

    return sb.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder smallestString = new StringBuilder(n);
    boolean zerosAllowed = n - 1 < k;

    for (int i = 0; i < n; i++) {
        if ( zerosAllowed && i == n - 1) {
            smallestString.append('0');
            break;
        }
        int currentChar = (char) ('a' + k % 26);
        smallestString.append(currentChar);
        k -= (currentChar - 'a');
        k /= 26;
        zerosAllowed = currentChar == '0';
    }

    return smallestString.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder(n);
    for (int i = 25; i >= 0 && k > 0; i--) {
        int gaps = n - (sb.length() - i * (i + 1) / 2);
        if (k >= gaps * (i + 1)) {
            k -= gaps * (i + 1);
            sb.append((char) ('a' + i));
        } else {
            int nChars = (gaps + k) / (i + 1);
            sb.append((char) ('a' + i));
            k -= nChars * (i + 1);
            for (int j = 0; j < nChars - 1; j++) {
                sb.append((char) ('a' + i - 1));
            }
            break;
        }
    }
    return sb.toString();
}

