public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            return 0;
        }

        int length = A.length;
        int[][] dp = new int[length + 1][0];
        for (int i = 1; i <= length; i++) {
            dp[i] = new int[2 * i];
            dp[i][i] = 1;
        }

        for (int i = 1; i <= length; i++) {
            for (int j = 0; j < i; j++) {
                int sum = A[i - 1] + A[j];
                if (Math.sqrt(sum) % 1 == 0) {
                    int index = (int) Math.sqrt(sum);
                    dp[i][index] = (dp[i][index] + dp[j][i - 2]) % 1000000007;
                }
            }
        }

        int result = 0;
        for (int i = length; i < 2 * length; i++) {
            result = (result + dp[length][i]) % 1000000007;
        }

        return result;
    }

