        int[] stack = new int[n];
        int maxArea = 0;
        int index;
        for (int i = 0; i < n; ++i) {
            while (!stack.isEmpty() && heights[stack[stack.length - 1]] >= heights[i]) {
                index = stack[stack.length - 1];
                maxArea = Math.max(maxArea, heights[index] * (stack.length == 1 ? i : i - stack[stack.length - 2] - 1));
                stack.pop();
            }
            stack.push(i);
        }
        while (!stack.isEmpty()) {
            index = stack[stack.length - 1];
