    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            leftSmaller[i] = -1;
        } else {
            leftSmaller[i] = stack.peek();
        }
        stack.push(i);
    }

    // Clear the stack
    stack.clear();

    // Calculate the index of the first smaller element to the right
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            rightSmaller[i] = n;
        } else {
            rightSmaller[i] = stack.peek();
