public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    // Initialize the result array
    int[] result = new int[mat.length * mat[0].length];
    int index = 0;

    // Directions for moving diagonally (down-right, down-left, up-right, up-left)
    int[][] directions = {{1, 1}, {1, -1}, {-1, 1}, {-1, -1}};

    // Directions from which to start (top-left to bottom-right)
    int[] startDirs = {{0, 0}, {0, mat[0].length - 1}, {mat.length - 1, 0}, {mat.length - 1, mat[0].length - 1}};

    // Start traversing the matrix
    for (int[] startDir : startDirs) {
        int rows = startDir[0] - 1;
        int cols = startDir[1] - 1;
        int dirIndex = 0;

        // Traverse until all elements in the current diagonal are visited
        while (rows >= 0 && rows < mat.length && cols >= 0 && cols < mat[0].length) {
            result[index++] = mat[rows][cols];
            rows += directions[dirIndex][0];
            cols += directions[dirIndex][1];
            dirIndex = (dirIndex + 1) % 4; // Move to the next direction
        }
    }

    return result;
}

