    List<Integer> result = new ArrayList<>();
    int m = mat.length;
    int n = mat[0].length;
    int row = 0;
    int col = 0;
    int move = 0;  // 0 for left to right, 1 for top to bottom
    while (row < m && col < n) {
        result.add(mat[row][col]);

        if (move == 0) {  // Moving left to right
            if (col + 1 != n && row == 0) row = 1;  // Move bottom-right to top-right
            else if (col + 1 == n && row != m - 1) row++;  // Move top-right to bottom-right
            else col++;  // Move to the right
        } else {  // Moving top to bottom
            if (row + 1 != m && col == 0) col = 1;  // Move right-left to top-left
            else if (row + 1 == m && col != n - 1) col++;  // Move top-left to bottom-left
            else row++;  // Move down
        }
    }
    int[] finalArray = new int[result.size()];
    for (int i = 0; i < result.size(); i++) {
        finalArray[i] = result.get(i);
    }
    return finalArray;
}

