        boolean[][] visited = new boolean[numRows][numCols];
        for (int i = 0; i < numRows * numCols; i++) {
            int[] topMost = queue.poll();
            order[i] = mat[topMost[0]][topMost[1]];
            visited[topMost[0]][topMost[1]] = true;

            int x direction = directionX[i % 2], y direction = directionY[i % 2];
            if (topMost[0] - direction >= 0 && !visited[topMost[0] - direction][topMost[1]]) {
                queue.add(new int[]{topMost[0] - direction, topMost[1]});
            }
            if (topMost[1] + direction < numCols && !visited[topMost[0]][topMost[1] + direction]) {
                queue.add(new int[]{topMost[0], topMost[1] + direction});
            }
        }

        return order;
    }

public static int[] diagonalOrder(int[][] mat) {
