        // Top to bottom diagonal
        for (int j = i; j >= 0 && j < mat[0].length; j--) {
            result[end] = mat[i][j];
            end++;
        }

        // Right to left diagonal
        for (int j = i + 1; j < mat.length && j < mat[0].length; j++) {
            result[end] = mat[j][i];
            end++;
        }
    }

    return result;
}

