public static int findSmallestInteger(int n) {
    // Convert the integer to a character array to manipulate the digits
    char[] digits = String.valueOf(n).toCharArray();

    int minLength = digits.length;
    int[] order = generateOrder(digits.length);

    for (int i = digits.length - 1; i > 0; i--) {
        if (order[i] > order[i - 1]) {
            // Find the smallest digit that can be placed after the current digit and greater than the current digit
            for (int j = i + 1; j < digits.length; j++) {
                if (order[j] > order[i] && digits[j] > digits[i]) {
                    char temp = digits[j];
                    digits[j] = digits[i];
                    digits[i] = temp;
                    // Reorder the remaining digits to form the smallest number
                    Arrays.sort(digits, order);
                    // Convert the character array back to an integer
                    return Integer.parseInt(String.valueOf(digits));
                }
            }
        }
    }

    // If no digits can be rearranged, return -1
    return -1;
}

