public static int findSmallestInteger(int n) {
    if (n == 0) return -1; // Zero cannot be rearranged to form a smaller number

    char[] digits = String.valueOf(n).toCharArray();
    int i = n % 10;

    for (int j = i - 1; j >= 0 && digits[j] >= digits[j + 1]; j--) {
        continue;
    }

    if (j < 0) return -1; // No such rearrangement exists

    for (int k = i - 1; k >= 0 && digits[j] <= digits[k]; k--) {
        continue;
    }

    swap(digits, j, k);
    Arrays.sort(digits, j + 1);

    return Integer.parseInt(new String(digits));
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int idx = -1;

    // Find the first digit that is smaller than the digit immediately following it
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            idx = i;
            break;
        }
    }

    if (idx == -1) {
        return -1; // No such rearrangement exists
    }

    // Find the smallest digit greater than digits[idx] to swap with
    for (int j = digits.length - 1; j >= idx; j--) {
        if (digits[j] > digits[idx]) {
            swap(digits, idx, j);
            break;
        }
    }

    // Reverse the digits from idx+1 to the end
    reverse(digits, idx + 1, digits.length - 1);

    return Integer.parseInt(new String(digits));
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> centerSymmetricNumbers = new ArrayList<>();
    for (int i = 0; i <= n / 2; i++) {
        StringBuilder leftHalf = new StringBuilder();
        StringBuilder rightHalf = new StringBuilder();

        // Generate left half of the center symmetric number
        for (int j = 0; j <= i; j++) {
            leftHalf.append(j);
        }

        // If left half is a single digit, right half is also a single digit
        if (leftHalf.length() == 1) {
            for (int j = i; j <= n / 2; j++) {
                rightHalf.append(n - j);
            }
        } else {
            // Generate right half of the center symmetric number
            for (int j = 0; j <= i; j++) {
                rightHalf.append(n - j);
            }
        }

        // Combine left and right half and reverse them to get a center symmetric number
        String centerSymmetricNumber = leftHalf.toString() + rightHalf.reverse().toString();
        centerSymmetricNumbers.add(centerSymmetricNumber);
    }
    return centerSymmetricNumbers;
}

