public static boolean isBoomerang(int[][] points) {
    int numPoints = points.length;
    if (numPoints != 3) {
        throw new IllegalArgumentException("Expected 3 points, got " + numPoints);
    }

    // Calculate vectors between consecutive points
    double x12 = points[1][0] - points[0][0];
    double y12 = points[1][1] - points[0][1];
    double x23 = points[2][0] - points[1][0];
    double y23 = points[2][1] - points[1][1];

    // Calculate the cross product of the vectors
    double crossProduct = x12 * y23 - y12 * x23;

    // A boomerang is formed if the cross product is non-zero
    return crossProduct != 0;
}

public static boolean isBoomerang(int[][] points) {
    int len = points.length;

    // Check if the points are not collinear
    if (isColinear(points)) {
        return false; // If they are collinear, the points do not form a boomerang
    }

    int area = 0;

    // Calculate the area using the determinant method
    for (int i = 0; i < len; i++) {
        int j = (i+1) % len;
        area += points[i][0] * points[j][1] - points[i][1] * points[j][0];
    }

    return Math.abs(area) != 0; // A non-zero area indicates the points form a boomerang
}

private static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate the areas of triangle formed with points x1, y1, x2, y2 and x1, y1, x3, y3
    int area1 = Math.abs((x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2.0);
    int area2 = Math.abs((x1 * (y3 - y2) + x3 * (y2 - y1) + x2 * (y1 - y3)) / 2.0);

    // Boomerang is formed if the areas are different
    return area1 != area2;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        return false; // At least 3 points are required to form a triangle
    }

    // Calculate the origin center of the triangle
    int centerX = (points[0][0] + points[1][0] + points[2][0]) / 3;
    int centerY = (points[0][1] + points[1][1] + points[2][1]) / 3;

    // Calculate the slopes of the opposite sides of the triangle
    double slope1 = (points[1][1] - centerY) / (points[1][0] - centerX);
    double slope2 = (points[2][1] - centerY) / (points[2][0] - centerX);
    double slope3 = (points[0][1] - centerY) / (points[0][0] - centerX);

    // Check if the slopes are distinct
    return slope1 != slope2 && slope2 != slope3;
}

