public static int findNthUglyNumber(int n) {
    Set<Long> seen = new HashSet<>();
    PriorityQueue<Long> pq = new PriorityQueue<>();
    long n1 = 1;
    long n2 = 2;
    long n3 = 3;

    pq.offer(n1);
    pq.offer(n2);
    pq.offer(n3);
    seen.add(n1);
    seen.add(n2);
    seen.add(n3);

    int count = 0;
    while (count < n) {
        long current = pq.poll();
        if (!seen.contains(current)) {
            seen.add(current);
            count++;
            pq.offer(current * 2);
            pq.offer(current * 3);
            pq.offer(current * 5);
        }
    }
    return (int) current;
}

