    String[] words = s.split(" ");
    StringBuilder reversedString = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        for (int i = 0, j = reversedWord.length() - 1; i < j; i++, j--) {
            char temp = reversedWord.charAt(i);
            reversedWord.setCharAt(i, reversedWord.charAt(j));
            reversedWord.setCharAt(j, temp);
        }
        reversedString.append(reversedWord).append(" ");
    }

    // Remove the trailing space
    return reversedString.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        result.append(reversedWord).append(" ");
    }

    return result.toString().trim();
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    StringBuilder wordBuf = new StringBuilder();
    for (char c : s.toCharArray()) {
        if (Character.isWhitespace(c)) {
            if (!wordBuf.isEmpty()) {
                result.append(new StringBuilder(wordBuf.reverse().toString()));
            }
            result.append(c);
            wordBuf.setLength(0); // Reset the word buffer
        } else {
            wordBuf.append(c);
        }
    }
    if (!wordBuf.isEmpty()) {
        result.append(new StringBuilder(wordBuf.reverse().toString()));
    }
    return result.toString();
}

public static String reverseWords(String s) {
    char[] chars = s.toCharArray();
    int i = 0, j = 0;
    while (j < chars.length) {
        char c = chars[j];
        if (c == ' ') {
            reverse(chars, i, j - 1);
            i = j + 1;
        }
        j++;
    }
    reverse(chars, i, j - 1);
    return new String(chars);
}

public static String reverseWords(String s) {
    StringBuilder sb = new StringBuilder();
    for (String word : s.split(" ")) {
        StringBuilder reversedWord = new StringBuilder(word);
        for (int i = 0; i < word.length() / 2; i++) {
            char temp = reversedWord.charAt(i);
            reversedWord.setCharAt(i, reversedWord.charAt(word.length() - i - 1));
            reversedWord.setCharAt(word.length() - i - 1, temp);
        }
        sb.append(reversedWord).append(" ");
    }
    return sb.toString().trim();
}
